import telnetlib
from taf.internal.managedobject import ManagedObject


class Telnet(ManagedObject, telnetlib.Telnet, object):
    """ Telnet process.

    """
    def __init__(self, host, port, timeout, *args, **kwargs):
        super(Telnet, self).__init__(**kwargs)
        self.__host = host
        self.__port = port
        self.__timeout = timeout

    def _setup(self):
        self.open(host=self.__host, port=self.__port, timeout=self.__timeout)

    def _teardown(self):
        self.close()
